// Hành trình hội nhập mẫu cho bản chạy thử (sinh từ Phần mềm nhân sự 0.6.1 – window.hnDemoExport(), 12/11/2026 13:20: biểu mẫu có người hoàn thiện)
export const DEMO_HN = {"DS007":{"v":1,"bm":{"BM01":{"ten":"Hợp đồng thử việc","loai":"hd","ghi":"Bản chính thức sẽ do phòng nhân sự soạn và gửi tới bạn. Đọc trước để nắm nội dung; mang theo CCCD khi ký.","nguoi":"hcns","html":"<p class=\"tp-p\" style=\"text-align:center\"><b>CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM</b></p><p class=\"tp-p\" style=\"text-align:center\"><b>Độc lập – Tự do – Hạnh phúc</b></p><p class=\"tp-p\" style=\"text-align:center\">———————</p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-h1\" style=\"text-align:center\">HỢP ĐỒNG THỬ VIỆC</p><p class=\"tp-p\" style=\"text-align:center\"><i>Số: </i><i><span class=\"tf-v\">06/2026/HĐTV-DS</span></i></p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-p\" style=\"text-align:justify\"><i>Căn cứ Bộ luật Lao động số 45/2019/QH14 ngày 20/11/2019;</i></p><p class=\"tp-p\" style=\"text-align:justify\"><i>Căn cứ Nghị định số 145/2020/NĐ-CP ngày 14/12/2020 của Chính phủ quy định chi tiết và hướng dẫn thi hành một số điều của Bộ luật Lao động về điều kiện lao động và quan hệ lao động;</i></p><p class=\"tp-p\" style=\"text-align:justify\"><i>Căn cứ nhu cầu và năng lực của hai bên,</i></p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-p\" style=\"text-align:justify\">Hôm nay, <span class=\"tf-v\">ngày 05 tháng 10 năm 2026</span>, tại <span class=\"tf-blank\">……………………</span>, chúng tôi gồm:</p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-p\" style=\"text-align:justify\"><b>BÊN A – NGƯỜI SỬ DỤNG LAO ĐỘNG: </b><b><span class=\"tf-v\">Công ty TNHH Đốm Sáng Edu</span></b></p><p class=\"tp-p\" style=\"text-align:justify\">Địa chỉ: <span class=\"tf-blank\">……………………</span></p><p class=\"tp-p\" style=\"text-align:justify\">Mã số thuế: <span class=\"tf-blank\">……………………</span></p><p class=\"tp-p\" style=\"text-align:justify\">Điện thoại: <span class=\"tf-blank\">……………………</span></p><p class=\"tp-p\" style=\"text-align:justify\">Người đại diện: <b><span class=\"tf-v\">Trần Quang Minh</span></b>    Chức vụ: <span class=\"tf-v\">Giám đốc</span></p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-p\" style=\"text-align:justify\"><b>BÊN B – NGƯỜI LAO ĐỘNG: </b><b><span class=\"tf-v\">Đặng Minh Khoa</span></b></p><p class=\"tp-p\" style=\"text-align:justify\">Giới tính: <span class=\"tf-v\">Nam</span>    Ngày sinh: <span class=\"tf-v\">14/06/2001</span>    Quốc tịch: Việt Nam</p><p class=\"tp-p\" style=\"text-align:justify\">Số CCCD: <span class=\"tf-v\">040001000007</span>    Ngày cấp: <span class=\"tf-v\">12/10/2021</span></p><p class=\"tp-p\" style=\"text-align:justify\">Nơi cư trú: <span class=\"tf-v\">Số 10, ngõ 214 đường Nguyễn Xiển, phường Thanh Liệt, TP Hà Nội</span></p><p class=\"tp-p\" style=\"text-align:justify\">Điện thoại: <span class=\"tf-v\">0900000107</span></p><p class=\"tp-p\" style=\"text-align:justify\">Trình độ: <span class=\"tf-v\">Đại học</span></p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-p\" style=\"text-align:justify\">Hai bên thỏa thuận ký kết hợp đồng thử việc và cam kết làm đúng những điều khoản sau đây:</p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-h2\" style=\"text-align:justify\">Điều 1. Công việc, thời gian thử việc và địa điểm làm việc</p><p class=\"tp-p\" style=\"text-align:justify\">1. Thời gian thử việc: <span class=\"tf-v\">từ ngày 05 tháng 10 năm 2026 đến ngày 03 tháng 12 năm 2026</span> (<span class=\"tf-v\">60</span> ngày).</p><p class=\"tp-p\" style=\"text-align:justify\">2. Chức danh: <span class=\"tf-v\">Giảng viên</span>; bộ phận: <span class=\"tf-v\">Bộ phận Giảng viên</span>.</p><p class=\"tp-p\" style=\"text-align:justify\">3. Công việc phải làm: theo bản mô tả công việc của chức danh và phân công của người quản lý trực tiếp.</p><p class=\"tp-p\" style=\"text-align:justify\">4. Địa điểm làm việc: <span class=\"tf-v\">trụ sở công ty</span>.</p><p class=\"tp-h2\" style=\"text-align:justify\">Điều 2. Thời giờ làm việc, thời giờ nghỉ ngơi</p><p class=\"tp-p\" style=\"text-align:justify\">1. Thời giờ làm việc: <span class=\"tf-v\">Thứ Hai – Thứ Sáu, từ 08:00 đến 17:00, nghỉ giữa ca 12:00 - 13:00</span>.</p><p class=\"tp-p\" style=\"text-align:justify\">2. Nghỉ lễ, tết và các chế độ nghỉ khác theo quy định của Bộ luật Lao động và nội quy lao động của Bên A.</p><p class=\"tp-h2\" style=\"text-align:justify\">Điều 3. Tiền lương thử việc</p><p class=\"tp-p\" style=\"text-align:justify\">1. Mức lương thử việc: <span class=\"tf-v\">5.310.000 đồng</span>/tháng (không thấp hơn 85% mức lương của công việc đó – Điều 26 Bộ luật Lao động).</p><p class=\"tp-p\" style=\"text-align:justify\">2. Hình thức trả lương: chuyển khoản vào tài khoản của Bên B tại <span class=\"tf-v\">Techcombank</span>; trả hằng tháng, chậm nhất vào ngày <span class=\"tf-v\">10</span> của tháng kế tiếp.</p><p class=\"tp-h2\" style=\"text-align:justify\">Điều 4. Kết thúc thời gian thử việc</p><p class=\"tp-p\" style=\"text-align:justify\">1. Khi kết thúc thời gian thử việc, Bên A thông báo kết quả thử việc cho Bên B. Trường hợp đạt yêu cầu, hai bên tiếp tục thực hiện hoặc giao kết hợp đồng lao động.</p><p class=\"tp-p\" style=\"text-align:justify\">2. Trong thời gian thử việc, mỗi bên có quyền hủy bỏ hợp đồng thử việc mà không cần báo trước và không phải bồi thường (Điều 27 Bộ luật Lao động).</p><p class=\"tp-h2\" style=\"text-align:justify\">Điều 5. Quyền và nghĩa vụ của Bên B</p><p class=\"tp-p\" style=\"text-align:justify\">1. Được trả lương đầy đủ, đúng hạn; được hưởng các chế độ theo quy định của pháp luật và quy chế của Bên A.</p><p class=\"tp-p\" style=\"text-align:justify\">2. Hoàn thành công việc được giao; chấp hành nội quy lao động, quy định an toàn, vệ sinh lao động; giữ bí mật thông tin, tài liệu của Bên A theo cam kết bảo mật.</p><p class=\"tp-h2\" style=\"text-align:justify\">Điều 6. Quyền và nghĩa vụ của Bên A</p><p class=\"tp-p\" style=\"text-align:justify\">1. Bảo đảm điều kiện làm việc và thực hiện đầy đủ các cam kết trong hợp đồng này.</p><p class=\"tp-p\" style=\"text-align:justify\">2. Trả lương đầy đủ, đúng hạn.</p><p class=\"tp-p\" style=\"text-align:justify\">3. Điều hành, quản lý Bên B theo nội quy lao động và quy định của pháp luật.</p><p class=\"tp-h2\" style=\"text-align:justify\">Điều 7. Điều khoản thi hành</p><p class=\"tp-p\" style=\"text-align:justify\">Hợp đồng có hiệu lực từ <span class=\"tf-v\">ngày 05 tháng 10 năm 2026</span>, lập thành 02 bản có giá trị như nhau, mỗi bên giữ 01 bản.</p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><div class=\"tp-sign\"><div><b>NGƯỜI LAO ĐỘNG</b><i>(Ký, ghi rõ họ tên)</i>Đặng Minh Khoa</div><div><b>NGƯỜI SỬ DỤNG LAO ĐỘNG</b><i>(Ký, đóng dấu, ghi rõ họ tên)</i>Trần Quang Minh</div></div>"},"BM02":{"ten":"Thỏa thuận bảo mật thông tin","loai":"soan","ghi":"Bản chính thức sẽ do phòng nhân sự soạn và gửi tới bạn, ký cùng hợp đồng thử việc trong ngày đầu.","nguoi":"hcns","html":"<p class=\"tp-p\" style=\"text-align:center\"><b>CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM</b></p><p class=\"tp-p\" style=\"text-align:center\"><b>Độc lập – Tự do – Hạnh phúc</b></p><p class=\"tp-p\" style=\"text-align:center\">———————</p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-h1\" style=\"text-align:center\">THỎA THUẬN BẢO MẬT THÔNG TIN</p><p class=\"tp-p\" style=\"text-align:center\"><i>Kèm theo hợp đồng thử việc, hợp đồng lao động</i></p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-p\" style=\"text-align:justify\"><i>Căn cứ khoản 2 Điều 21 Bộ luật Lao động số 45/2019/QH14;</i></p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-p\" style=\"text-align:justify\"><b>BÊN A – NGƯỜI SỬ DỤNG LAO ĐỘNG: </b><b><span class=\"tf-v\">Công ty TNHH Đốm Sáng Edu</span></b></p><p class=\"tp-p\" style=\"text-align:justify\">Địa chỉ: <span class=\"tf-blank\">……………………</span></p><p class=\"tp-p\" style=\"text-align:justify\">Người đại diện: <span class=\"tf-v\">Trần Quang Minh</span>    Chức vụ: <span class=\"tf-v\">Giám đốc</span></p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-p\" style=\"text-align:justify\"><b>BÊN B – NGƯỜI LAO ĐỘNG: </b><b><span class=\"tf-v\">Đặng Minh Khoa</span></b></p><p class=\"tp-p\" style=\"text-align:justify\">Mã NV: <span class=\"tf-v\">DS007</span>    Chức danh: <span class=\"tf-v\">Giảng viên</span>    Bộ phận: <span class=\"tf-v\">Bộ phận Giảng viên</span></p><p class=\"tp-p\" style=\"text-align:justify\">Số CCCD: <span class=\"tf-v\">040001000007</span>    Điện thoại: <span class=\"tf-v\">0900000107</span></p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-h2\" style=\"text-align:justify\">Điều 1. Thông tin cần bảo mật</p><p class=\"tp-p\" style=\"text-align:justify\">Thông tin khách hàng, đối tác, giá bán, chi phí, số liệu tài chính; dữ liệu cá nhân của người lao động và khách hàng; quy trình, tài liệu nội bộ; tài khoản phần mềm và các thông tin khác Bên A đánh dấu &quot;Mật&quot; hoặc thông báo cần bảo mật.</p><p class=\"tp-h2\" style=\"text-align:justify\">Điều 2. Trách nhiệm của Bên B</p><p class=\"tp-p\" style=\"text-align:justify\">1. Chỉ dùng thông tin cần bảo mật để làm công việc được giao; không sao chép, gửi, đăng tải ra ngoài khi chưa được Bên A đồng ý bằng văn bản.</p><p class=\"tp-p\" style=\"text-align:justify\">2. Không chia sẻ mật khẩu, tài khoản được cấp; báo ngay cho người quản lý khi phát hiện thông tin bị lộ.</p><p class=\"tp-p\" style=\"text-align:justify\">3. Khi nghỉ việc, bàn giao lại toàn bộ tài liệu, dữ liệu, thiết bị có chứa thông tin cần bảo mật.</p><p class=\"tp-h2\" style=\"text-align:justify\">Điều 3. Thời hạn bảo mật</p><p class=\"tp-p\" style=\"text-align:justify\">Trong suốt thời gian làm việc và ……… tháng kể từ ngày chấm dứt hợp đồng.</p><p class=\"tp-h2\" style=\"text-align:justify\">Điều 4. Xử lý vi phạm</p><p class=\"tp-p\" style=\"text-align:justify\">Vi phạm thỏa thuận này được xử lý theo nội quy lao động của Bên A và quy định của pháp luật; bên vi phạm bồi thường thiệt hại thực tế đã gây ra.</p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-p\" style=\"text-align:justify\">Thỏa thuận lập thành 02 bản, mỗi bên giữ 01 bản, có hiệu lực từ ngày ký.</p><div class=\"tp-sign\"><div><b>NGƯỜI LAO ĐỘNG</b><i>(Ký, ghi rõ họ tên)</i>Đặng Minh Khoa</div><div><b>NGƯỜI SỬ DỤNG LAO ĐỘNG</b><i>(Ký, đóng dấu, ghi rõ họ tên)</i>Trần Quang Minh</div></div>"},"BM03":{"ten":"Biên bản bàn giao tài sản, công cụ làm việc","loai":"soan","ghi":"Bản chính thức sẽ do phòng nhân sự soạn và gửi tới bạn khi bàn giao. Kiểm tra từng món trước khi ký.","nguoi":"hcns","html":"<p class=\"tp-p\" style=\"text-align:center\"><b><span class=\"tf-v\">Công ty TNHH Đốm Sáng Edu</span></b></p><p class=\"tp-p\" style=\"text-align:center\">———————</p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-h1\" style=\"text-align:center\">BIÊN BẢN BÀN GIAO TÀI SẢN, CÔNG CỤ LÀM VIỆC</p><p class=\"tp-p\" style=\"text-align:center\"><i>Ngày bàn giao: </i><i><span class=\"tf-v\">05/10/2026</span></i></p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-p\" style=\"text-align:justify\">Bên giao: Phòng Hành chính nhân sự – <span class=\"tf-v\">Nguyễn Thị Thu Hà</span></p><p class=\"tp-p\" style=\"text-align:justify\">Bên nhận: <b><span class=\"tf-v\">Đặng Minh Khoa</span></b>    Mã NV: <span class=\"tf-v\">DS007</span></p><p class=\"tp-p\" style=\"text-align:justify\">Chức danh: <span class=\"tf-v\">Giảng viên</span>    Bộ phận: <span class=\"tf-v\">Bộ phận Giảng viên</span></p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-h2\" style=\"text-align:justify\">Tài sản, công cụ bàn giao</p><p class=\"tp-p\" style=\"text-align:justify\">1. Máy tính (loại, số máy): ……………………………………………………………………………………</p><p class=\"tp-p\" style=\"text-align:justify\">2. Thẻ ra vào số: ……………………………………………………………………………………</p><p class=\"tp-p\" style=\"text-align:justify\">3. Đồng phục (số bộ, cỡ): ……………………………………………………………………………………</p><p class=\"tp-p\" style=\"text-align:justify\">4. Chìa khóa tủ số: ……………………………………………………………………………………</p><p class=\"tp-p\" style=\"text-align:justify\">5. Thiết bị, công cụ khác: ……………………………………………………………………………………</p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-p\" style=\"text-align:justify\">Bên nhận đã kiểm tra, nhận đủ các tài sản, công cụ trên trong tình trạng sử dụng tốt; có trách nhiệm giữ gìn, dùng đúng mục đích và bàn giao lại khi nghỉ việc hoặc khi công ty yêu cầu.</p><p class=\"tp-p\" style=\"text-align:justify\">Biên bản lập thành 02 bản, mỗi bên giữ 01 bản.</p><div class=\"tp-sign\"><div><b>NGƯỜI LAO ĐỘNG</b><i>(Ký, ghi rõ họ tên)</i>Đặng Minh Khoa</div><div><b>NGƯỜI SỬ DỤNG LAO ĐỘNG</b><i>(Ký, đóng dấu, ghi rõ họ tên)</i>Trần Quang Minh</div></div>"},"BM04":{"ten":"Phiếu trao đổi tuần đầu","loai":"soan","ghi":"Ghi trước vài ý để buổi trò chuyện cuối tuần đầu hiệu quả hơn.","nguoi":"nv","html":"<p class=\"tp-h1\" style=\"text-align:center\">PHIẾU TRAO ĐỔI TUẦN ĐẦU</p><p class=\"tp-p\" style=\"text-align:center\"><i>Người mới ghi trước buổi trò chuyện cuối tuần đầu</i></p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-p\" style=\"text-align:justify\">Họ và tên: <b><span class=\"tf-v\">Đặng Minh Khoa</span></b>    Chức danh: <span class=\"tf-v\">Giảng viên</span>    Bộ phận: <span class=\"tf-v\">Bộ phận Giảng viên</span></p><p class=\"tp-p\" style=\"text-align:justify\">Ngày vào làm: <span class=\"tf-v\">05/10/2026</span>    Người đồng hành: <span class=\"tf-v\">Trịnh Văn Long</span></p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-h2\" style=\"text-align:justify\">1. Điều bạn thấy thuận lợi trong tuần đầu</p><p class=\"tp-p\" style=\"text-align:justify\">……………………………………………………………………………………</p><p class=\"tp-p\" style=\"text-align:justify\">……………………………………………………………………………………</p><p class=\"tp-h2\" style=\"text-align:justify\">2. Điều còn vướng, chưa rõ</p><p class=\"tp-p\" style=\"text-align:justify\">……………………………………………………………………………………</p><p class=\"tp-p\" style=\"text-align:justify\">……………………………………………………………………………………</p><p class=\"tp-h2\" style=\"text-align:justify\">3. Hỗ trợ bạn cần thêm (tài liệu, công cụ, người hướng dẫn)</p><p class=\"tp-p\" style=\"text-align:justify\">……………………………………………………………………………………</p><p class=\"tp-p\" style=\"text-align:justify\">……………………………………………………………………………………</p><p class=\"tp-h2\" style=\"text-align:justify\">4. Việc bạn muốn làm tốt hơn ở tuần tới</p><p class=\"tp-p\" style=\"text-align:justify\">……………………………………………………………………………………</p><p class=\"tp-p\" style=\"text-align:justify\">……………………………………………………………………………………</p><p class=\"tp-h2\" style=\"text-align:justify\">Nhận xét của trưởng bộ phận</p><p class=\"tp-p\" style=\"text-align:justify\">……………………………………………………………………………………</p><p class=\"tp-p\" style=\"text-align:justify\">……………………………………………………………………………………</p>"},"BM05":{"ten":"Phiếu tự đánh giá kết quả thử việc","loai":"soan","ghi":"Điền rồi gửi trưởng bộ phận trước buổi đánh giá kết quả thử việc.","nguoi":"nv","html":"<p class=\"tp-h1\" style=\"text-align:center\">PHIẾU TỰ ĐÁNH GIÁ KẾT QUẢ THỬ VIỆC</p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-p\" style=\"text-align:justify\">Họ và tên: <b><span class=\"tf-v\">Đặng Minh Khoa</span></b>    Mã NV: <span class=\"tf-v\">DS007</span></p><p class=\"tp-p\" style=\"text-align:justify\">Chức danh: <span class=\"tf-v\">Giảng viên</span>    Bộ phận: <span class=\"tf-v\">Bộ phận Giảng viên</span></p><p class=\"tp-p\" style=\"text-align:justify\">Thời gian thử việc: từ <span class=\"tf-v\">05/10/2026</span> đến <span class=\"tf-v\">03/12/2026</span></p><p class=\"tp-p\" style=\"text-align:justify\">Trưởng bộ phận: <span class=\"tf-v\">Bùi Văn Thắng</span></p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-h2\" style=\"text-align:justify\">1. Kết quả theo mục tiêu đã giao</p><p class=\"tp-p\" style=\"text-align:justify\">Mục tiêu 1: ……………………………… Kết quả: ……………………………… Tự chấm (1–5): ……</p><p class=\"tp-p\" style=\"text-align:justify\">Mục tiêu 2: ……………………………… Kết quả: ……………………………… Tự chấm (1–5): ……</p><p class=\"tp-p\" style=\"text-align:justify\">Mục tiêu 3: ……………………………… Kết quả: ……………………………… Tự chấm (1–5): ……</p><p class=\"tp-h2\" style=\"text-align:justify\">2. Việc bạn đã làm tốt</p><p class=\"tp-p\" style=\"text-align:justify\">……………………………………………………………………………………</p><p class=\"tp-p\" style=\"text-align:justify\">……………………………………………………………………………………</p><p class=\"tp-h2\" style=\"text-align:justify\">3. Việc cần cải thiện</p><p class=\"tp-p\" style=\"text-align:justify\">……………………………………………………………………………………</p><p class=\"tp-p\" style=\"text-align:justify\">……………………………………………………………………………………</p><p class=\"tp-h2\" style=\"text-align:justify\">4. Hỗ trợ cần thêm từ công ty, bộ phận</p><p class=\"tp-p\" style=\"text-align:justify\">……………………………………………………………………………………</p><p class=\"tp-h2\" style=\"text-align:justify\">5. Mong muốn, định hướng sau thời gian thử việc</p><p class=\"tp-p\" style=\"text-align:justify\">……………………………………………………………………………………</p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-p\" style=\"text-align:center\"><i>Ngày …… tháng …… năm ……</i></p><p class=\"tp-p\" style=\"text-align:center\"><b>NGƯỜI TỰ ĐÁNH GIÁ</b></p><p class=\"tp-p\" style=\"text-align:center\"><i>(Ký, ghi rõ họ tên)</i></p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-p\" style=\"text-align:center\"><b><span class=\"tf-v\">Đặng Minh Khoa</span></b></p>"},"BM06":{"ten":"Hợp đồng lao động","loai":"hd","ghi":"Bản chính thức sẽ do phòng nhân sự soạn và gửi tới bạn.","nguoi":"hcns","html":"<p class=\"tp-p\" style=\"text-align:center\"><b>CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM</b></p><p class=\"tp-p\" style=\"text-align:center\"><b>Độc lập – Tự do – Hạnh phúc</b></p><p class=\"tp-p\" style=\"text-align:center\">———————</p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-h1\" style=\"text-align:center\">HỢP ĐỒNG LAO ĐỘNG</p><p class=\"tp-p\" style=\"text-align:center\"><i>Số: </i><i><span class=\"tf-blank\">……………………</span></i></p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-p\" style=\"text-align:justify\"><i>Căn cứ Bộ luật Lao động số 45/2019/QH14 ngày 20/11/2019;</i></p><p class=\"tp-p\" style=\"text-align:justify\"><i>Căn cứ Nghị định số 145/2020/NĐ-CP ngày 14/12/2020 của Chính phủ quy định chi tiết và hướng dẫn thi hành một số điều của Bộ luật Lao động về điều kiện lao động và quan hệ lao động;</i></p><p class=\"tp-p\" style=\"text-align:justify\"><i>Căn cứ nhu cầu và năng lực của hai bên,</i></p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-p\" style=\"text-align:justify\">Hôm nay, <span class=\"tf-v\">ngày …… tháng …… năm ……</span>, tại <span class=\"tf-blank\">……………………</span>, chúng tôi gồm:</p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-p\" style=\"text-align:justify\"><b>BÊN A – NGƯỜI SỬ DỤNG LAO ĐỘNG: </b><b><span class=\"tf-v\">Công ty TNHH Đốm Sáng Edu</span></b></p><p class=\"tp-p\" style=\"text-align:justify\">Địa chỉ: <span class=\"tf-blank\">……………………</span></p><p class=\"tp-p\" style=\"text-align:justify\">Mã số thuế: <span class=\"tf-blank\">……………………</span></p><p class=\"tp-p\" style=\"text-align:justify\">Điện thoại: <span class=\"tf-blank\">……………………</span></p><p class=\"tp-p\" style=\"text-align:justify\">Người đại diện: <b><span class=\"tf-v\">Trần Quang Minh</span></b>    Chức vụ: <span class=\"tf-v\">Giám đốc</span></p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-p\" style=\"text-align:justify\"><b>BÊN B – NGƯỜI LAO ĐỘNG: </b><b><span class=\"tf-v\">Đặng Minh Khoa</span></b></p><p class=\"tp-p\" style=\"text-align:justify\">Giới tính: <span class=\"tf-v\">Nam</span>    Ngày sinh: <span class=\"tf-v\">14/06/2001</span>    Quốc tịch: Việt Nam</p><p class=\"tp-p\" style=\"text-align:justify\">Số CCCD: <span class=\"tf-v\">040001000007</span>    Ngày cấp: <span class=\"tf-v\">12/10/2021</span></p><p class=\"tp-p\" style=\"text-align:justify\">Nơi cư trú: <span class=\"tf-v\">Số 10, ngõ 214 đường Nguyễn Xiển, phường Thanh Liệt, TP Hà Nội</span></p><p class=\"tp-p\" style=\"text-align:justify\">Điện thoại: <span class=\"tf-v\">0900000107</span></p><p class=\"tp-p\" style=\"text-align:justify\">Trình độ: <span class=\"tf-v\">Đại học</span></p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-p\" style=\"text-align:justify\">Hai bên thỏa thuận ký kết hợp đồng lao động và cam kết làm đúng những điều khoản sau đây:</p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-h2\" style=\"text-align:justify\">Điều 1. Thời hạn hợp đồng, công việc và địa điểm làm việc</p><p class=\"tp-p\" style=\"text-align:justify\">1. Loại hợp đồng: <span class=\"tf-blank\">……………………</span>; thời hạn <span class=\"tf-v\">không xác định thời hạn, bắt đầu từ ngày …… tháng …… năm ……</span>.</p><p class=\"tp-p\" style=\"text-align:justify\">2. Chức danh: <span class=\"tf-v\">Giảng viên</span>; bộ phận: <span class=\"tf-v\">Bộ phận Giảng viên</span>.</p><p class=\"tp-p\" style=\"text-align:justify\">3. Công việc phải làm: theo bản mô tả công việc của chức danh và phân công của người quản lý trực tiếp.</p><p class=\"tp-p\" style=\"text-align:justify\">4. Địa điểm làm việc: <span class=\"tf-v\">trụ sở công ty</span>.</p><p class=\"tp-h2\" style=\"text-align:justify\">Điều 2. Thời giờ làm việc, thời giờ nghỉ ngơi</p><p class=\"tp-p\" style=\"text-align:justify\">1. Thời giờ làm việc: <span class=\"tf-v\">Thứ Hai – Thứ Sáu, từ 08:00 đến 17:00, nghỉ giữa ca 12:00 - 13:00</span>.</p><p class=\"tp-p\" style=\"text-align:justify\">2. Nghỉ hằng năm, nghỉ lễ, tết, nghỉ việc riêng và các chế độ nghỉ khác theo quy định của Bộ luật Lao động và nội quy lao động của Bên A.</p><p class=\"tp-h2\" style=\"text-align:justify\">Điều 3. Tiền lương, phụ cấp và hình thức trả lương</p><p class=\"tp-p\" style=\"text-align:justify\">1. Mức lương (lương cơ bản – căn cứ đóng bảo hiểm xã hội): <span class=\"tf-blank\">……………………</span>/tháng.</p><p class=\"tp-p\" style=\"text-align:justify\">2. Phụ cấp lương và các khoản bổ sung khác:</p><p class=\"tp-p\" style=\"text-align:justify\">– Phụ cấp, khoản bổ sung khác (nếu có): ghi tại phụ lục hợp đồng lao động.</p><p class=\"tp-p\" style=\"text-align:justify\">3. Chế độ phúc lợi, trợ cấp khác (tiền ăn giữa ca, hỗ trợ điện thoại, đi lại, trang phục, chuyên cần…): theo Quy chế lương, thưởng và phúc lợi của Bên A ban hành, công bố từng thời kỳ; mức hưởng tính theo ngày công thực tế.</p><p class=\"tp-p\" style=\"text-align:justify\">4. Hình thức trả lương: chuyển khoản vào tài khoản của Bên B tại <span class=\"tf-v\">Techcombank</span>; trả hằng tháng, chậm nhất vào ngày <span class=\"tf-v\">10</span> của tháng kế tiếp.</p><p class=\"tp-p\" style=\"text-align:justify\">5. Chế độ nâng lương, thưởng: theo quy chế lương, thưởng của Bên A.</p><p class=\"tp-h2\" style=\"text-align:justify\">Điều 4. Bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp</p><p class=\"tp-p\" style=\"text-align:justify\">Bên A và Bên B tham gia bảo hiểm xã hội bắt buộc, bảo hiểm y tế, bảo hiểm thất nghiệp theo quy định của pháp luật hiện hành; mức đóng theo quy định tại thời điểm đóng.</p><p class=\"tp-h2\" style=\"text-align:justify\">Điều 5. Quyền và nghĩa vụ của Bên B</p><p class=\"tp-p\" style=\"text-align:justify\">1. Được trả lương đầy đủ, đúng hạn; được hưởng các chế độ theo quy định của pháp luật và quy chế của Bên A.</p><p class=\"tp-p\" style=\"text-align:justify\">2. Hoàn thành công việc được giao; chấp hành nội quy lao động, quy định an toàn, vệ sinh lao động; giữ bí mật thông tin, tài liệu của Bên A theo cam kết bảo mật.</p><p class=\"tp-p\" style=\"text-align:justify\">3. Bồi thường thiệt hại do vi phạm theo quy định của pháp luật và nội quy lao động.</p><p class=\"tp-h2\" style=\"text-align:justify\">Điều 6. Quyền và nghĩa vụ của Bên A</p><p class=\"tp-p\" style=\"text-align:justify\">1. Bảo đảm việc làm, điều kiện làm việc và thực hiện đầy đủ các cam kết trong hợp đồng này.</p><p class=\"tp-p\" style=\"text-align:justify\">2. Trả lương đầy đủ, đúng hạn; đóng bảo hiểm cho Bên B theo quy định.</p><p class=\"tp-p\" style=\"text-align:justify\">3. Điều hành, quản lý Bên B theo nội quy lao động và quy định của pháp luật.</p><p class=\"tp-h2\" style=\"text-align:justify\">Điều 7. Điều khoản thi hành</p><p class=\"tp-p\" style=\"text-align:justify\">1. Những vấn đề chưa ghi trong hợp đồng này thực hiện theo nội quy lao động, thỏa ước lao động tập thể (nếu có) và quy định của pháp luật lao động.</p><p class=\"tp-p\" style=\"text-align:justify\">2. Hợp đồng có hiệu lực từ <span class=\"tf-v\">ngày …… tháng …… năm ……</span>, lập thành 02 bản có giá trị như nhau, mỗi bên giữ 01 bản.</p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><div class=\"tp-sign\"><div><b>NGƯỜI LAO ĐỘNG</b><i>(Ký, ghi rõ họ tên)</i>Đặng Minh Khoa</div><div><b>NGƯỜI SỬ DỤNG LAO ĐỘNG</b><i>(Ký, đóng dấu, ghi rõ họ tên)</i>Trần Quang Minh</div></div>"},"BM07":{"ten":"Phiếu góp ý hành trình hội nhập","loai":"soan","ghi":"Góp ý thật lòng để hành trình của người mới sau tốt hơn.","nguoi":"nv","html":"<p class=\"tp-h1\" style=\"text-align:center\">PHIẾU GÓP Ý HÀNH TRÌNH HỘI NHẬP</p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-p\" style=\"text-align:justify\">Họ và tên: <span class=\"tf-v\">Đặng Minh Khoa</span>    Bộ phận: <span class=\"tf-v\">Bộ phận Giảng viên</span>    Ngày vào làm: <span class=\"tf-v\">05/10/2026</span></p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-h2\" style=\"text-align:justify\">1. Ngày đầu bạn có được chuẩn bị đủ chỗ ngồi, thiết bị, tài khoản không?</p><p class=\"tp-p\" style=\"text-align:justify\">☐ Đã đủ    ☐ Còn thiếu: ……………………………………………………………………………………</p><p class=\"tp-h2\" style=\"text-align:justify\">2. Người đồng hành có hỗ trợ bạn kịp thời không?</p><p class=\"tp-p\" style=\"text-align:justify\">☐ Rất kịp thời    ☐ Bình thường    ☐ Chưa kịp thời – vì: ……………………………………………………………………………………</p><p class=\"tp-h2\" style=\"text-align:justify\">3. Thông tin về nội quy, chế độ, cách làm việc có rõ ràng không?</p><p class=\"tp-p\" style=\"text-align:justify\">☐ Rõ ràng    ☐ Còn chưa rõ: ……………………………………………………………………………………</p><p class=\"tp-h2\" style=\"text-align:justify\">4. Công ty nên làm khác đi điều gì để người mới sau thuận lợi hơn?</p><p class=\"tp-p\" style=\"text-align:justify\">……………………………………………………………………………………</p><p class=\"tp-p\" style=\"text-align:justify\">……………………………………………………………………………………</p>"}},"id":"HN01","ten":"Đặng Minh Khoa","cty":"Công ty TNHH Đốm Sáng Edu","cd":"Giảng viên","pb":"Bộ phận Giảng viên","start":"2026-10-05","pe":"2026-12-03","jname":"Hành trình hội nhập - CHUNG","xong":0,"who":{"hcns":"Nguyễn Thị Thu Hà","tbp":"Bùi Văn Thắng","kc":"Trịnh Văn Long","kt":"Nguyễn Thị Thu Hà","bgd":"Trần Quang Minh","it":"Nguyễn Thị Thu Hà"},"ph":[["pre","Trước ngày đi làm","Chuẩn bị để ngày đầu không ai bị động"],["d1","Ngày đầu tiên","Đón, ký hồ sơ, phổ biến nội quy, bàn giao về bộ phận"],["w1","Tuần đầu tiên","Đồng hành, giới thiệu, trao đổi cuối tuần"],["pr","Trong thời gian thử việc","Theo dõi tiến độ, góp ý định kỳ"],["end","Kết thúc thử việc","Đánh giá và thông báo kết quả"],["off","Chính thức – chào đón","Ký hợp đồng, BHXH, chào đón thành viên mới"]],"roles":{"hcns":"Hành chính nhân sự","tbp":"Trưởng bộ phận","kc":"Người đồng hành","kt":"Kế toán","bgd":"Ban giám đốc","it":"Phụ trách thiết bị, tài khoản","nv":"Người mới"},"steps":[{"id":"b01","ph":"pre","due":"2026-09-30","t1":"","t2":"","title":"Xác nhận ngày đi làm, báo các bên liên quan","desc":"Xác nhận lại với người mới ngày giờ đi làm, địa điểm, người đón. Báo trưởng bộ phận và kế toán để chuẩn bị chỗ ngồi và tính lương từ ngày vào làm.","doc":"Thư mời nhận việc đã ký · Tên, số điện thoại người đón","own":"hcns","own2":["tbp","kt"],"x":"done","dAt":"2026-09-30","req":1,"law":"","bm":[],"moi":"co"},{"id":"b02","ph":"pre","due":"2026-10-02","t1":"","t2":"","title":"Gửi thư chào mừng và danh sách giấy tờ cần mang","desc":"Gửi qua email hoặc Zalo: giờ có mặt, địa chỉ, trang phục, người liên hệ. Ghi rõ giấy tờ mang theo để đối chiếu và nộp bản sao: CCCD, văn bằng, sổ BHXH, giấy khám sức khỏe.","doc":"Mẫu thư chào mừng · Danh sách giấy tờ cần mang · Bản đồ đường đến công ty","own":"hcns","own2":[],"x":"done","dAt":"2026-10-02","req":1,"law":"BLLĐ 2019 Điều 17 khoản 1 – không giữ bản chính giấy tờ tùy thân, văn bằng, chứng chỉ","bm":[],"moi":"co"},{"id":"b03","ph":"pre","due":"2026-10-03","t1":"","t2":"","title":"Soạn sẵn bộ hồ sơ ký ngày đầu","desc":"Hợp đồng thử việc, thỏa thuận bảo mật thông tin, biên bản bàn giao tài sản. Kiểm tra lương thử việc, số ngày thử việc khớp với thư mời nhận việc.","doc":"Hợp đồng thử việc (2 bản) · Thỏa thuận bảo mật thông tin · Biên bản bàn giao tài sản","own":"hcns","own2":[],"x":"done","dAt":"2026-10-03","req":1,"law":"BLLĐ 2019 Điều 24, 25 (thời gian thử việc), 26 (lương thử việc ít nhất 85%)","bm":[],"moi":""},{"id":"b04","ph":"pre","due":"2026-10-03","t1":"","t2":"","title":"Chuẩn bị chỗ ngồi, thiết bị, tài khoản","desc":"Sắp xếp chỗ ngồi, cài đặt máy tính; tạo email công ty, tài khoản phần mềm, thêm vào nhóm chat nội bộ; làm thẻ ra vào, đặt đồng phục đúng cỡ.","doc":"Bàn ghế · Máy tính · Email công ty · Tài khoản phần mềm · Nhóm chat nội bộ · Thẻ ra vào · Đồng phục","own":"it","own2":["hcns"],"x":"done","dAt":"2026-10-03","req":1,"law":"","bm":[],"moi":""},{"id":"b05","ph":"pre","due":"2026-10-04","t1":"","t2":"","title":"Phân công người đồng hành và lịch tuần đầu","desc":"Chọn một người cùng bộ phận đồng hành cùng người mới trong tháng đầu (có thể khác trưởng bộ phận). Lên lịch tuần đầu: ai hướng dẫn việc gì, ngày nào; gửi lịch cho phòng nhân sự.","doc":"Lịch tuần đầu · Danh sách đầu mối phối hợp","own":"tbp","own2":["kc"],"x":"done","dAt":"2026-10-04","req":1,"law":"","bm":[],"moi":""},{"id":"b06","ph":"pre","due":"2026-10-04","t1":"","t2":"","title":"Chuẩn bị quà chào đón","desc":"Chuẩn bị bộ quà tặng kèm thiệp chào mừng có chữ ký trưởng bộ phận – nhỏ nhưng tạo ấn tượng tốt ngày đầu.","doc":"Bộ quà tặng: sổ, bút, bình nước · Thiệp chào mừng có chữ ký trưởng bộ phận","own":"hcns","own2":[],"x":"done","dAt":"2026-10-04","req":0,"law":"","bm":[],"moi":""},{"id":"b07","ph":"d1","due":"2026-10-05","t1":"08:00","t2":"08:15","title":"Đón người mới, giới thiệu người phụ trách hội nhập","desc":"Đón ở lối vào, mời nước, giới thiệu bản thân và lịch ngày đầu; tặng quà chào đón.","doc":"Bộ quà tặng · Lịch ngày đầu in sẵn · Nước uống","own":"hcns","own2":[],"x":"done","dAt":"2026-10-05","req":1,"law":"","bm":[],"moi":"co"},{"id":"b08","ph":"d1","due":"2026-10-05","t1":"08:15","t2":"08:45","title":"Ký hồ sơ nhận việc, nhận bản sao giấy tờ","desc":"Người mới đọc kỹ rồi ký hợp đồng thử việc và các văn bản đã soạn. Giám đốc (hoặc người được ủy quyền) ký, giao lại người mới 01 bản. Chỉ nhận bản sao giấy tờ, đối chiếu bản chính rồi trả lại ngay.","doc":"Bộ hồ sơ ký ngày đầu (2 bản) · Con dấu · Túi hồ sơ lưu bản sao giấy tờ","own":"hcns","own2":["bgd","nv"],"x":"done","dAt":"2026-10-05","req":1,"law":"BLLĐ 2019 Điều 17 khoản 1, Điều 24","bm":["BM01","BM02"],"moi":"co"},{"id":"b09","ph":"d1","due":"2026-10-05","t1":"08:45","t2":"09:00","title":"Cấp tài khoản app, hướng dẫn người mới tự cập nhật hồ sơ","desc":"Cấp tài khoản app nhân viên, cùng người mới đăng nhập và chấm công thử một lần. Hướng dẫn người mới tự cập nhật hồ sơ trên app: CCCD, ngày sinh, địa chỉ, tài khoản ngân hàng, người phụ thuộc. Phòng nhân sự kiểm tra lại thông tin người mới gửi.","doc":"Tài khoản app nhân viên (mã đăng nhập, PIN) · Hướng dẫn chấm công Wi‑Fi","own":"hcns","own2":["nv"],"x":"done","dAt":"2026-10-05","req":1,"law":"","bm":[],"moi":"co"},{"id":"b10","ph":"d1","due":"2026-10-05","t1":"09:00","t2":"10:00","title":"Tìm hiểu công ty, nội quy và chế độ trên app","desc":"Người mới tự đọc, xem khóa đào tạo nội bộ “Hội nhập” trên app nhân viên: lịch sử, sứ mệnh, giá trị, sơ đồ tổ chức, sản phẩm – dịch vụ; nội quy lao động, giờ làm, chấm công, nghỉ phép, kỳ trả lương, thưởng và phúc lợi. Học xong bấm xác nhận đã đọc nội quy; phòng nhân sự giải đáp thắc mắc.","doc":"Khóa đào tạo nội bộ “Hội nhập” trên app · Nội quy lao động · Sổ tay nhân viên","own":"nv","own2":["hcns"],"x":"done","dAt":"2026-10-05","req":1,"law":"BLLĐ 2019 Điều 118 khoản 4 – nội quy lao động phải được thông báo đến người lao động","bm":[],"moi":"own"},{"id":"b11","ph":"d1","due":"2026-10-05","t1":"10:00","t2":"10:30","title":"Giới thiệu với các phòng ban, bàn giao về bộ phận","desc":"Dẫn người mới chào ban giám đốc, trưởng các bộ phận và đồng nghiệp; bàn giao cho trưởng bộ phận và người đồng hành.","doc":"Sơ đồ tổ chức · Danh sách người cần chào","own":"hcns","own2":["tbp","kc"],"x":"done","dAt":"2026-10-05","req":1,"law":"","bm":[],"moi":"co"},{"id":"b12","ph":"d1","due":"2026-10-05","t1":"13:30","t2":"14:30","title":"Giao mô tả công việc và mục tiêu tuần đầu","desc":"Trưởng bộ phận trao đổi mô tả công việc, kết quả mong đợi trong thời gian thử việc, mục tiêu tuần đầu và cách đánh giá.","doc":"Mô tả công việc · Mục tiêu thử việc · Tiêu chí đánh giá","own":"tbp","own2":["kc"],"x":"done","dAt":"2026-10-05","req":1,"law":"","bm":[],"moi":"co"},{"id":"b13","ph":"d1","due":"2026-10-05","t1":"14:30","t2":"15:00","title":"Bàn giao tài sản, công cụ làm việc","desc":"Bàn giao máy tính, thiết bị, thẻ ra vào, đồng phục, chìa khóa tủ; hai bên ký biên bản.","doc":"Biên bản bàn giao (2 bản) · Máy tính · Thẻ ra vào · Đồng phục · Chìa khóa tủ","own":"hcns","own2":["it"],"x":"done","dAt":"2026-10-07","req":0,"law":"","bm":["BM03"],"moi":"co"},{"id":"b14","ph":"d1","due":"2026-10-05","t1":"16:30","t2":"17:00","title":"Hỏi thăm cuối ngày đầu","desc":"Trò chuyện 10–15 phút: ngày đầu thế nào, còn vướng gì, cần hỗ trợ gì; ghi lại để xử lý ngay.","doc":"Phiếu ghi nhận ý kiến ngày đầu","own":"hcns","own2":[],"x":"done","dAt":"2026-10-05","req":0,"law":"","bm":[],"moi":"co"},{"id":"b15","ph":"w1","due":"2026-10-06","t1":"","t2":"","title":"Đồng hành trong công việc hằng ngày","desc":"Người đồng hành hướng dẫn quy trình, công cụ, đầu mối phối hợp; giao việc nhỏ để người mới làm thử và góp ý ngay trong ngày.","doc":"Danh sách việc giao thử · Tài liệu quy trình của bộ phận","own":"kc","own2":["tbp"],"x":"done","dAt":"2026-10-06","req":1,"law":"","bm":[],"moi":"co"},{"id":"b16","ph":"w1","due":"2026-10-07","t1":"","t2":"","title":"Giới thiệu người mới với toàn công ty","desc":"Đăng lời chào mừng trên nhóm chat hoặc bản tin nội bộ: tên, vị trí, bộ phận. Hỏi ý người mới trước khi đăng ảnh, thông tin cá nhân.","doc":"Ảnh và lời giới thiệu đã được người mới đồng ý","own":"hcns","own2":[],"x":"skip","dAt":"2026-10-07","req":0,"law":"","bm":[],"moi":""},{"id":"b17","ph":"w1","due":"2026-10-11","t1":"","t2":"","title":"Trò chuyện đánh giá tuần đầu","desc":"Người mới tự nhìn lại tuần đầu (thuận lợi, khó khăn, cần hỗ trợ); trưởng bộ phận nhận xét. Đây là trao đổi nội bộ để hỗ trợ kịp thời – không thay cho thông báo kết quả thử việc.","doc":"Phiếu trao đổi tuần đầu","own":"hcns","own2":["tbp","nv"],"x":"done","dAt":"2026-10-11","req":1,"law":"","bm":["BM04"],"moi":"co"},{"id":"b18","ph":"pr","due":"2026-11-03","t1":"","t2":"","title":"Gặp định kỳ giữa thời gian thử việc","desc":"Xem tiến độ so với mục tiêu thử việc, góp ý cụ thể, điều chỉnh hỗ trợ.","doc":"Bảng theo dõi mục tiêu thử việc","own":"tbp","own2":["hcns"],"x":"todo","dAt":"","req":0,"law":"","bm":[],"moi":"co"},{"id":"b23","ph":"end","due":"2026-11-23","t1":"","t2":"","title":"Người mới tự đánh giá kết quả thử việc","desc":"Tự nhìn lại các mục tiêu đã giao: việc đã làm tốt, việc cần cải thiện, hỗ trợ cần thêm. Gửi trưởng bộ phận trước buổi đánh giá kết quả thử việc.","doc":"Phiếu tự đánh giá thử việc","own":"nv","own2":["tbp"],"x":"todo","dAt":"","req":1,"law":"","bm":["BM05"],"moi":"own"},{"id":"b19","ph":"end","due":"2026-11-26","t1":"","t2":"","title":"Trưởng bộ phận đánh giá kết quả thử việc","desc":"Đánh giá theo mục tiêu đã giao ngày đầu; đề xuất Đạt / Không đạt gửi phòng nhân sự và ban giám đốc.","doc":"Phiếu đánh giá kết quả thử việc","own":"tbp","own2":["hcns"],"x":"todo","dAt":"","req":1,"law":"","bm":[],"moi":""},{"id":"b20","ph":"end","due":"2026-12-03","t1":"","t2":"","title":"Thông báo kết quả thử việc cho người lao động","desc":"Thông báo khi kết thúc thời gian thử việc. Đạt: ký hợp đồng lao động. Không đạt: chấm dứt hợp đồng thử việc.","doc":"Thông báo kết quả thử việc","own":"hcns","own2":["bgd"],"x":"todo","dAt":"","req":1,"law":"BLLĐ 2019 Điều 27","bm":[],"moi":"co"},{"id":"b21","ph":"off","due":"2026-12-04","t1":"","t2":"","title":"Ký hợp đồng lao động, đăng ký BHXH","desc":"Ký hợp đồng lao động, cập nhật lương chính thức. Kế toán đăng ký tham gia BHXH, BHYT, BHTN cho người lao động.","doc":"Hợp đồng lao động (2 bản) · Quyết định lương chính thức · Hồ sơ đăng ký BHXH","own":"hcns","own2":["kt"],"x":"todo","dAt":"","req":1,"law":"Luật BHXH 2024 – thời hạn đăng ký tham gia (chưa trích điều)","bm":["BM06"],"moi":"co"},{"id":"b22","ph":"off","due":"2026-12-06","t1":"","t2":"","title":"Chào đón thành viên chính thức","desc":"Chúc mừng trong buổi họp hoặc nhóm chung; trao thẻ nhân viên, đồng phục. Hỏi người mới góp ý về quá trình hội nhập để cải thiện hành trình.","doc":"Thẻ nhân viên · Đồng phục · Quà chúc mừng · Phiếu góp ý hội nhập","own":"hcns","own2":["nv"],"x":"todo","dAt":"","req":0,"law":"","bm":["BM07"],"moi":"co"}]},"SG005":{"v":1,"bm":{"BM01":{"ten":"Hợp đồng thử việc","loai":"hd","ghi":"Bản chính thức sẽ do phòng nhân sự soạn và gửi tới bạn. Đọc trước để nắm nội dung; mang theo CCCD khi ký.","nguoi":"hcns","html":"<p class=\"tp-p\" style=\"text-align:center\"><b>CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM</b></p><p class=\"tp-p\" style=\"text-align:center\"><b>Độc lập – Tự do – Hạnh phúc</b></p><p class=\"tp-p\" style=\"text-align:center\">———————</p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-h1\" style=\"text-align:center\">HỢP ĐỒNG THỬ VIỆC</p><p class=\"tp-p\" style=\"text-align:center\"><i>Số: </i><i><span class=\"tf-v\">04/2026/HĐTV-SG</span></i></p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-p\" style=\"text-align:justify\"><i>Căn cứ Bộ luật Lao động số 45/2019/QH14 ngày 20/11/2019;</i></p><p class=\"tp-p\" style=\"text-align:justify\"><i>Căn cứ Nghị định số 145/2020/NĐ-CP ngày 14/12/2020 của Chính phủ quy định chi tiết và hướng dẫn thi hành một số điều của Bộ luật Lao động về điều kiện lao động và quan hệ lao động;</i></p><p class=\"tp-p\" style=\"text-align:justify\"><i>Căn cứ nhu cầu và năng lực của hai bên,</i></p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-p\" style=\"text-align:justify\">Hôm nay, <span class=\"tf-v\">ngày 11 tháng 09 năm 2026</span>, tại <span class=\"tf-blank\">……………………</span>, chúng tôi gồm:</p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-p\" style=\"text-align:justify\"><b>BÊN A – NGƯỜI SỬ DỤNG LAO ĐỘNG: </b><b><span class=\"tf-v\">Công ty TNHH Đốm Sáng Health</span></b></p><p class=\"tp-p\" style=\"text-align:justify\">Địa chỉ: <span class=\"tf-blank\">……………………</span></p><p class=\"tp-p\" style=\"text-align:justify\">Mã số thuế: <span class=\"tf-blank\">……………………</span></p><p class=\"tp-p\" style=\"text-align:justify\">Điện thoại: <span class=\"tf-blank\">……………………</span></p><p class=\"tp-p\" style=\"text-align:justify\">Người đại diện: <b><span class=\"tf-v\">Lý Thanh Tùng</span></b>    Chức vụ: <span class=\"tf-v\">Giám đốc</span></p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-p\" style=\"text-align:justify\"><b>BÊN B – NGƯỜI LAO ĐỘNG: </b><b><span class=\"tf-v\">Phan Gia Bảo</span></b></p><p class=\"tp-p\" style=\"text-align:justify\">Giới tính: <span class=\"tf-v\">Nam</span>    Ngày sinh: <span class=\"tf-v\">30/07/2003</span>    Quốc tịch: Việt Nam</p><p class=\"tp-p\" style=\"text-align:justify\">Số CCCD: <span class=\"tf-v\">089003000025</span>    Ngày cấp: <span class=\"tf-v\">10/10/2021</span></p><p class=\"tp-p\" style=\"text-align:justify\">Nơi cư trú: <span class=\"tf-v\">Số 7 hẻm 51 đường Cao Thắng, phường Bàn Cờ, TP Hồ Chí Minh</span></p><p class=\"tp-p\" style=\"text-align:justify\">Điện thoại: <span class=\"tf-v\">0900000125</span></p><p class=\"tp-p\" style=\"text-align:justify\">Trình độ: <span class=\"tf-v\">Cao đẳng</span></p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-p\" style=\"text-align:justify\">Hai bên thỏa thuận ký kết hợp đồng thử việc và cam kết làm đúng những điều khoản sau đây:</p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-h2\" style=\"text-align:justify\">Điều 1. Công việc, thời gian thử việc và địa điểm làm việc</p><p class=\"tp-p\" style=\"text-align:justify\">1. Thời gian thử việc: <span class=\"tf-v\">từ ngày 14 tháng 09 năm 2026 đến ngày 12 tháng 11 năm 2026</span> (<span class=\"tf-v\">60</span> ngày).</p><p class=\"tp-p\" style=\"text-align:justify\">2. Chức danh: <span class=\"tf-v\">Công nhân sản xuất</span>; bộ phận: <span class=\"tf-v\">Xưởng Sản xuất</span>.</p><p class=\"tp-p\" style=\"text-align:justify\">3. Công việc phải làm: theo bản mô tả công việc của chức danh và phân công của người quản lý trực tiếp.</p><p class=\"tp-p\" style=\"text-align:justify\">4. Địa điểm làm việc: <span class=\"tf-v\">trụ sở công ty</span>.</p><p class=\"tp-h2\" style=\"text-align:justify\">Điều 2. Thời giờ làm việc, thời giờ nghỉ ngơi</p><p class=\"tp-p\" style=\"text-align:justify\">1. Thời giờ làm việc: <span class=\"tf-v\">Thứ Hai – Thứ Sáu, từ 08:00 đến 17:00, nghỉ giữa ca 12:00 - 13:00</span>.</p><p class=\"tp-p\" style=\"text-align:justify\">2. Nghỉ lễ, tết và các chế độ nghỉ khác theo quy định của Bộ luật Lao động và nội quy lao động của Bên A.</p><p class=\"tp-h2\" style=\"text-align:justify\">Điều 3. Tiền lương thử việc</p><p class=\"tp-p\" style=\"text-align:justify\">1. Mức lương thử việc: <span class=\"tf-v\">5.310.000 đồng</span>/tháng (không thấp hơn 85% mức lương của công việc đó – Điều 26 Bộ luật Lao động).</p><p class=\"tp-p\" style=\"text-align:justify\">2. Hình thức trả lương: chuyển khoản vào tài khoản của Bên B tại <span class=\"tf-v\">MB Bank</span>; trả hằng tháng, chậm nhất vào ngày <span class=\"tf-v\">10</span> của tháng kế tiếp.</p><p class=\"tp-h2\" style=\"text-align:justify\">Điều 4. Kết thúc thời gian thử việc</p><p class=\"tp-p\" style=\"text-align:justify\">1. Khi kết thúc thời gian thử việc, Bên A thông báo kết quả thử việc cho Bên B. Trường hợp đạt yêu cầu, hai bên tiếp tục thực hiện hoặc giao kết hợp đồng lao động.</p><p class=\"tp-p\" style=\"text-align:justify\">2. Trong thời gian thử việc, mỗi bên có quyền hủy bỏ hợp đồng thử việc mà không cần báo trước và không phải bồi thường (Điều 27 Bộ luật Lao động).</p><p class=\"tp-h2\" style=\"text-align:justify\">Điều 5. Quyền và nghĩa vụ của Bên B</p><p class=\"tp-p\" style=\"text-align:justify\">1. Được trả lương đầy đủ, đúng hạn; được hưởng các chế độ theo quy định của pháp luật và quy chế của Bên A.</p><p class=\"tp-p\" style=\"text-align:justify\">2. Hoàn thành công việc được giao; chấp hành nội quy lao động, quy định an toàn, vệ sinh lao động; giữ bí mật thông tin, tài liệu của Bên A theo cam kết bảo mật.</p><p class=\"tp-h2\" style=\"text-align:justify\">Điều 6. Quyền và nghĩa vụ của Bên A</p><p class=\"tp-p\" style=\"text-align:justify\">1. Bảo đảm điều kiện làm việc và thực hiện đầy đủ các cam kết trong hợp đồng này.</p><p class=\"tp-p\" style=\"text-align:justify\">2. Trả lương đầy đủ, đúng hạn.</p><p class=\"tp-p\" style=\"text-align:justify\">3. Điều hành, quản lý Bên B theo nội quy lao động và quy định của pháp luật.</p><p class=\"tp-h2\" style=\"text-align:justify\">Điều 7. Điều khoản thi hành</p><p class=\"tp-p\" style=\"text-align:justify\">Hợp đồng có hiệu lực từ <span class=\"tf-v\">ngày 14 tháng 09 năm 2026</span>, lập thành 02 bản có giá trị như nhau, mỗi bên giữ 01 bản.</p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><div class=\"tp-sign\"><div><b>NGƯỜI LAO ĐỘNG</b><i>(Ký, ghi rõ họ tên)</i>Phan Gia Bảo</div><div><b>NGƯỜI SỬ DỤNG LAO ĐỘNG</b><i>(Ký, đóng dấu, ghi rõ họ tên)</i>Lý Thanh Tùng</div></div>"},"BM02":{"ten":"Thỏa thuận bảo mật thông tin","loai":"soan","ghi":"Bản chính thức sẽ do phòng nhân sự soạn và gửi tới bạn, ký cùng hợp đồng thử việc trong ngày đầu.","nguoi":"hcns","html":"<p class=\"tp-p\" style=\"text-align:center\"><b>CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM</b></p><p class=\"tp-p\" style=\"text-align:center\"><b>Độc lập – Tự do – Hạnh phúc</b></p><p class=\"tp-p\" style=\"text-align:center\">———————</p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-h1\" style=\"text-align:center\">THỎA THUẬN BẢO MẬT THÔNG TIN</p><p class=\"tp-p\" style=\"text-align:center\"><i>Kèm theo hợp đồng thử việc, hợp đồng lao động</i></p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-p\" style=\"text-align:justify\"><i>Căn cứ khoản 2 Điều 21 Bộ luật Lao động số 45/2019/QH14;</i></p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-p\" style=\"text-align:justify\"><b>BÊN A – NGƯỜI SỬ DỤNG LAO ĐỘNG: </b><b><span class=\"tf-v\">Công ty TNHH Đốm Sáng Health</span></b></p><p class=\"tp-p\" style=\"text-align:justify\">Địa chỉ: <span class=\"tf-blank\">……………………</span></p><p class=\"tp-p\" style=\"text-align:justify\">Người đại diện: <span class=\"tf-v\">Lý Thanh Tùng</span>    Chức vụ: <span class=\"tf-v\">Giám đốc</span></p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-p\" style=\"text-align:justify\"><b>BÊN B – NGƯỜI LAO ĐỘNG: </b><b><span class=\"tf-v\">Phan Gia Bảo</span></b></p><p class=\"tp-p\" style=\"text-align:justify\">Mã NV: <span class=\"tf-v\">SG005</span>    Chức danh: <span class=\"tf-v\">Công nhân sản xuất</span>    Bộ phận: <span class=\"tf-v\">Xưởng Sản xuất</span></p><p class=\"tp-p\" style=\"text-align:justify\">Số CCCD: <span class=\"tf-v\">089003000025</span>    Điện thoại: <span class=\"tf-v\">0900000125</span></p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-h2\" style=\"text-align:justify\">Điều 1. Thông tin cần bảo mật</p><p class=\"tp-p\" style=\"text-align:justify\">Thông tin khách hàng, đối tác, giá bán, chi phí, số liệu tài chính; dữ liệu cá nhân của người lao động và khách hàng; quy trình, tài liệu nội bộ; tài khoản phần mềm và các thông tin khác Bên A đánh dấu &quot;Mật&quot; hoặc thông báo cần bảo mật.</p><p class=\"tp-h2\" style=\"text-align:justify\">Điều 2. Trách nhiệm của Bên B</p><p class=\"tp-p\" style=\"text-align:justify\">1. Chỉ dùng thông tin cần bảo mật để làm công việc được giao; không sao chép, gửi, đăng tải ra ngoài khi chưa được Bên A đồng ý bằng văn bản.</p><p class=\"tp-p\" style=\"text-align:justify\">2. Không chia sẻ mật khẩu, tài khoản được cấp; báo ngay cho người quản lý khi phát hiện thông tin bị lộ.</p><p class=\"tp-p\" style=\"text-align:justify\">3. Khi nghỉ việc, bàn giao lại toàn bộ tài liệu, dữ liệu, thiết bị có chứa thông tin cần bảo mật.</p><p class=\"tp-h2\" style=\"text-align:justify\">Điều 3. Thời hạn bảo mật</p><p class=\"tp-p\" style=\"text-align:justify\">Trong suốt thời gian làm việc và ……… tháng kể từ ngày chấm dứt hợp đồng.</p><p class=\"tp-h2\" style=\"text-align:justify\">Điều 4. Xử lý vi phạm</p><p class=\"tp-p\" style=\"text-align:justify\">Vi phạm thỏa thuận này được xử lý theo nội quy lao động của Bên A và quy định của pháp luật; bên vi phạm bồi thường thiệt hại thực tế đã gây ra.</p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-p\" style=\"text-align:justify\">Thỏa thuận lập thành 02 bản, mỗi bên giữ 01 bản, có hiệu lực từ ngày ký.</p><div class=\"tp-sign\"><div><b>NGƯỜI LAO ĐỘNG</b><i>(Ký, ghi rõ họ tên)</i>Phan Gia Bảo</div><div><b>NGƯỜI SỬ DỤNG LAO ĐỘNG</b><i>(Ký, đóng dấu, ghi rõ họ tên)</i>Lý Thanh Tùng</div></div>"},"BM03":{"ten":"Biên bản bàn giao tài sản, công cụ làm việc","loai":"soan","ghi":"Bản chính thức sẽ do phòng nhân sự soạn và gửi tới bạn khi bàn giao. Kiểm tra từng món trước khi ký.","nguoi":"hcns","html":"<p class=\"tp-p\" style=\"text-align:center\"><b><span class=\"tf-v\">Công ty TNHH Đốm Sáng Health</span></b></p><p class=\"tp-p\" style=\"text-align:center\">———————</p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-h1\" style=\"text-align:center\">BIÊN BẢN BÀN GIAO TÀI SẢN, CÔNG CỤ LÀM VIỆC</p><p class=\"tp-p\" style=\"text-align:center\"><i>Ngày bàn giao: </i><i><span class=\"tf-v\">14/09/2026</span></i></p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-p\" style=\"text-align:justify\">Bên giao: Phòng Hành chính nhân sự – <span class=\"tf-v\">Trịnh Thị Kim Ngân</span></p><p class=\"tp-p\" style=\"text-align:justify\">Bên nhận: <b><span class=\"tf-v\">Phan Gia Bảo</span></b>    Mã NV: <span class=\"tf-v\">SG005</span></p><p class=\"tp-p\" style=\"text-align:justify\">Chức danh: <span class=\"tf-v\">Công nhân sản xuất</span>    Bộ phận: <span class=\"tf-v\">Xưởng Sản xuất</span></p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-h2\" style=\"text-align:justify\">Tài sản, công cụ bàn giao</p><p class=\"tp-p\" style=\"text-align:justify\">1. Máy tính (loại, số máy): ……………………………………………………………………………………</p><p class=\"tp-p\" style=\"text-align:justify\">2. Thẻ ra vào số: ……………………………………………………………………………………</p><p class=\"tp-p\" style=\"text-align:justify\">3. Đồng phục (số bộ, cỡ): ……………………………………………………………………………………</p><p class=\"tp-p\" style=\"text-align:justify\">4. Chìa khóa tủ số: ……………………………………………………………………………………</p><p class=\"tp-p\" style=\"text-align:justify\">5. Thiết bị, công cụ khác: ……………………………………………………………………………………</p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-p\" style=\"text-align:justify\">Bên nhận đã kiểm tra, nhận đủ các tài sản, công cụ trên trong tình trạng sử dụng tốt; có trách nhiệm giữ gìn, dùng đúng mục đích và bàn giao lại khi nghỉ việc hoặc khi công ty yêu cầu.</p><p class=\"tp-p\" style=\"text-align:justify\">Biên bản lập thành 02 bản, mỗi bên giữ 01 bản.</p><div class=\"tp-sign\"><div><b>NGƯỜI LAO ĐỘNG</b><i>(Ký, ghi rõ họ tên)</i>Phan Gia Bảo</div><div><b>NGƯỜI SỬ DỤNG LAO ĐỘNG</b><i>(Ký, đóng dấu, ghi rõ họ tên)</i>Lý Thanh Tùng</div></div>"},"BM04":{"ten":"Phiếu trao đổi tuần đầu","loai":"soan","ghi":"Ghi trước vài ý để buổi trò chuyện cuối tuần đầu hiệu quả hơn.","nguoi":"nv","html":"<p class=\"tp-h1\" style=\"text-align:center\">PHIẾU TRAO ĐỔI TUẦN ĐẦU</p><p class=\"tp-p\" style=\"text-align:center\"><i>Người mới ghi trước buổi trò chuyện cuối tuần đầu</i></p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-p\" style=\"text-align:justify\">Họ và tên: <b><span class=\"tf-v\">Phan Gia Bảo</span></b>    Chức danh: <span class=\"tf-v\">Công nhân sản xuất</span>    Bộ phận: <span class=\"tf-v\">Xưởng Sản xuất</span></p><p class=\"tp-p\" style=\"text-align:justify\">Ngày vào làm: <span class=\"tf-v\">14/09/2026</span>    Người đồng hành: <span class=\"tf-v\">Võ Thành Đạt</span></p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-h2\" style=\"text-align:justify\">1. Điều bạn thấy thuận lợi trong tuần đầu</p><p class=\"tp-p\" style=\"text-align:justify\">……………………………………………………………………………………</p><p class=\"tp-p\" style=\"text-align:justify\">……………………………………………………………………………………</p><p class=\"tp-h2\" style=\"text-align:justify\">2. Điều còn vướng, chưa rõ</p><p class=\"tp-p\" style=\"text-align:justify\">……………………………………………………………………………………</p><p class=\"tp-p\" style=\"text-align:justify\">……………………………………………………………………………………</p><p class=\"tp-h2\" style=\"text-align:justify\">3. Hỗ trợ bạn cần thêm (tài liệu, công cụ, người hướng dẫn)</p><p class=\"tp-p\" style=\"text-align:justify\">……………………………………………………………………………………</p><p class=\"tp-p\" style=\"text-align:justify\">……………………………………………………………………………………</p><p class=\"tp-h2\" style=\"text-align:justify\">4. Việc bạn muốn làm tốt hơn ở tuần tới</p><p class=\"tp-p\" style=\"text-align:justify\">……………………………………………………………………………………</p><p class=\"tp-p\" style=\"text-align:justify\">……………………………………………………………………………………</p><p class=\"tp-h2\" style=\"text-align:justify\">Nhận xét của trưởng bộ phận</p><p class=\"tp-p\" style=\"text-align:justify\">……………………………………………………………………………………</p><p class=\"tp-p\" style=\"text-align:justify\">……………………………………………………………………………………</p>"},"BM05":{"ten":"Phiếu tự đánh giá kết quả thử việc","loai":"soan","ghi":"Điền rồi gửi trưởng bộ phận trước buổi đánh giá kết quả thử việc.","nguoi":"nv","html":"<p class=\"tp-h1\" style=\"text-align:center\">PHIẾU TỰ ĐÁNH GIÁ KẾT QUẢ THỬ VIỆC</p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-p\" style=\"text-align:justify\">Họ và tên: <b><span class=\"tf-v\">Phan Gia Bảo</span></b>    Mã NV: <span class=\"tf-v\">SG005</span></p><p class=\"tp-p\" style=\"text-align:justify\">Chức danh: <span class=\"tf-v\">Công nhân sản xuất</span>    Bộ phận: <span class=\"tf-v\">Xưởng Sản xuất</span></p><p class=\"tp-p\" style=\"text-align:justify\">Thời gian thử việc: từ <span class=\"tf-v\">14/09/2026</span> đến <span class=\"tf-v\">12/11/2026</span></p><p class=\"tp-p\" style=\"text-align:justify\">Trưởng bộ phận: <span class=\"tf-v\">Lê Văn Phát</span></p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-h2\" style=\"text-align:justify\">1. Kết quả theo mục tiêu đã giao</p><p class=\"tp-p\" style=\"text-align:justify\">Mục tiêu 1: ……………………………… Kết quả: ……………………………… Tự chấm (1–5): ……</p><p class=\"tp-p\" style=\"text-align:justify\">Mục tiêu 2: ……………………………… Kết quả: ……………………………… Tự chấm (1–5): ……</p><p class=\"tp-p\" style=\"text-align:justify\">Mục tiêu 3: ……………………………… Kết quả: ……………………………… Tự chấm (1–5): ……</p><p class=\"tp-h2\" style=\"text-align:justify\">2. Việc bạn đã làm tốt</p><p class=\"tp-p\" style=\"text-align:justify\">……………………………………………………………………………………</p><p class=\"tp-p\" style=\"text-align:justify\">……………………………………………………………………………………</p><p class=\"tp-h2\" style=\"text-align:justify\">3. Việc cần cải thiện</p><p class=\"tp-p\" style=\"text-align:justify\">……………………………………………………………………………………</p><p class=\"tp-p\" style=\"text-align:justify\">……………………………………………………………………………………</p><p class=\"tp-h2\" style=\"text-align:justify\">4. Hỗ trợ cần thêm từ công ty, bộ phận</p><p class=\"tp-p\" style=\"text-align:justify\">……………………………………………………………………………………</p><p class=\"tp-h2\" style=\"text-align:justify\">5. Mong muốn, định hướng sau thời gian thử việc</p><p class=\"tp-p\" style=\"text-align:justify\">……………………………………………………………………………………</p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-p\" style=\"text-align:center\"><i>Ngày …… tháng …… năm ……</i></p><p class=\"tp-p\" style=\"text-align:center\"><b>NGƯỜI TỰ ĐÁNH GIÁ</b></p><p class=\"tp-p\" style=\"text-align:center\"><i>(Ký, ghi rõ họ tên)</i></p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-p\" style=\"text-align:center\"><b><span class=\"tf-v\">Phan Gia Bảo</span></b></p>"},"BM06":{"ten":"Hợp đồng lao động","loai":"hd","ghi":"Bản chính thức sẽ do phòng nhân sự soạn và gửi tới bạn.","nguoi":"hcns","html":"<p class=\"tp-p\" style=\"text-align:center\"><b>CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM</b></p><p class=\"tp-p\" style=\"text-align:center\"><b>Độc lập – Tự do – Hạnh phúc</b></p><p class=\"tp-p\" style=\"text-align:center\">———————</p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-h1\" style=\"text-align:center\">HỢP ĐỒNG LAO ĐỘNG</p><p class=\"tp-p\" style=\"text-align:center\"><i>Số: </i><i><span class=\"tf-blank\">……………………</span></i></p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-p\" style=\"text-align:justify\"><i>Căn cứ Bộ luật Lao động số 45/2019/QH14 ngày 20/11/2019;</i></p><p class=\"tp-p\" style=\"text-align:justify\"><i>Căn cứ Nghị định số 145/2020/NĐ-CP ngày 14/12/2020 của Chính phủ quy định chi tiết và hướng dẫn thi hành một số điều của Bộ luật Lao động về điều kiện lao động và quan hệ lao động;</i></p><p class=\"tp-p\" style=\"text-align:justify\"><i>Căn cứ nhu cầu và năng lực của hai bên,</i></p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-p\" style=\"text-align:justify\">Hôm nay, <span class=\"tf-v\">ngày …… tháng …… năm ……</span>, tại <span class=\"tf-blank\">……………………</span>, chúng tôi gồm:</p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-p\" style=\"text-align:justify\"><b>BÊN A – NGƯỜI SỬ DỤNG LAO ĐỘNG: </b><b><span class=\"tf-v\">Công ty TNHH Đốm Sáng Health</span></b></p><p class=\"tp-p\" style=\"text-align:justify\">Địa chỉ: <span class=\"tf-blank\">……………………</span></p><p class=\"tp-p\" style=\"text-align:justify\">Mã số thuế: <span class=\"tf-blank\">……………………</span></p><p class=\"tp-p\" style=\"text-align:justify\">Điện thoại: <span class=\"tf-blank\">……………………</span></p><p class=\"tp-p\" style=\"text-align:justify\">Người đại diện: <b><span class=\"tf-v\">Lý Thanh Tùng</span></b>    Chức vụ: <span class=\"tf-v\">Giám đốc</span></p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-p\" style=\"text-align:justify\"><b>BÊN B – NGƯỜI LAO ĐỘNG: </b><b><span class=\"tf-v\">Phan Gia Bảo</span></b></p><p class=\"tp-p\" style=\"text-align:justify\">Giới tính: <span class=\"tf-v\">Nam</span>    Ngày sinh: <span class=\"tf-v\">30/07/2003</span>    Quốc tịch: Việt Nam</p><p class=\"tp-p\" style=\"text-align:justify\">Số CCCD: <span class=\"tf-v\">089003000025</span>    Ngày cấp: <span class=\"tf-v\">10/10/2021</span></p><p class=\"tp-p\" style=\"text-align:justify\">Nơi cư trú: <span class=\"tf-v\">Số 7 hẻm 51 đường Cao Thắng, phường Bàn Cờ, TP Hồ Chí Minh</span></p><p class=\"tp-p\" style=\"text-align:justify\">Điện thoại: <span class=\"tf-v\">0900000125</span></p><p class=\"tp-p\" style=\"text-align:justify\">Trình độ: <span class=\"tf-v\">Cao đẳng</span></p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-p\" style=\"text-align:justify\">Hai bên thỏa thuận ký kết hợp đồng lao động và cam kết làm đúng những điều khoản sau đây:</p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-h2\" style=\"text-align:justify\">Điều 1. Thời hạn hợp đồng, công việc và địa điểm làm việc</p><p class=\"tp-p\" style=\"text-align:justify\">1. Loại hợp đồng: <span class=\"tf-blank\">……………………</span>; thời hạn <span class=\"tf-v\">không xác định thời hạn, bắt đầu từ ngày …… tháng …… năm ……</span>.</p><p class=\"tp-p\" style=\"text-align:justify\">2. Chức danh: <span class=\"tf-v\">Công nhân sản xuất</span>; bộ phận: <span class=\"tf-v\">Xưởng Sản xuất</span>.</p><p class=\"tp-p\" style=\"text-align:justify\">3. Công việc phải làm: theo bản mô tả công việc của chức danh và phân công của người quản lý trực tiếp.</p><p class=\"tp-p\" style=\"text-align:justify\">4. Địa điểm làm việc: <span class=\"tf-v\">trụ sở công ty</span>.</p><p class=\"tp-h2\" style=\"text-align:justify\">Điều 2. Thời giờ làm việc, thời giờ nghỉ ngơi</p><p class=\"tp-p\" style=\"text-align:justify\">1. Thời giờ làm việc: làm việc theo ca. Bên A xếp lịch ca làm việc <span class=\"tf-v\">theo tuần</span> và thông báo cho Bên B trước khi bắt đầu kỳ; các ca làm việc hiện hành: <span class=\"tf-v\">Ca ngày (Full) (F) 08:00–17:00; Ca đêm (Đ) 22:00–07:00; Ca sáng (S) 07:00–11:00; Ca chiều (C) 13:00–17:00; Ca tối (T) 18:00–22:00</span>.</p><p class=\"tp-p\" style=\"text-align:justify\">2. Ngày nghỉ hằng tuần không cố định, theo lịch xếp ca; mỗi tuần Bên B được nghỉ ít nhất 01 ngày (24 giờ liên tục). Giữa hai ca làm việc liên tiếp, Bên B được nghỉ ít nhất 12 giờ.</p><p class=\"tp-p\" style=\"text-align:justify\">3. Nghỉ hằng năm, nghỉ lễ, tết, nghỉ việc riêng và các chế độ nghỉ khác theo quy định của Bộ luật Lao động và nội quy lao động của Bên A.</p><p class=\"tp-h2\" style=\"text-align:justify\">Điều 3. Tiền lương, phụ cấp và hình thức trả lương</p><p class=\"tp-p\" style=\"text-align:justify\">1. Mức lương (lương cơ bản – căn cứ đóng bảo hiểm xã hội): <span class=\"tf-blank\">……………………</span>/tháng, tương ứng <span class=\"tf-v\">208</span> giờ làm việc tiêu chuẩn/tháng.</p><p class=\"tp-p\" style=\"text-align:justify\">2. Phụ cấp lương và các khoản bổ sung khác:</p><p class=\"tp-p\" style=\"text-align:justify\">– Phụ cấp, khoản bổ sung khác (nếu có): ghi tại phụ lục hợp đồng lao động.</p><p class=\"tp-p\" style=\"text-align:justify\">3. Chế độ phúc lợi, trợ cấp khác (tiền ăn giữa ca, hỗ trợ điện thoại, đi lại, trang phục, chuyên cần…): theo Quy chế lương, thưởng và phúc lợi của Bên A ban hành, công bố từng thời kỳ; mức hưởng tính theo số ca, giờ làm thực tế.</p><p class=\"tp-p\" style=\"text-align:justify\">4. Hình thức trả lương: trả theo thời gian làm việc thực tế. Tiền lương tháng = số giờ làm việc thực tế trong tháng (theo lịch xếp ca và dữ liệu chấm công) × đơn giá giờ; đơn giá giờ = (mức lương + phụ cấp lương cố định) ÷ <span class=\"tf-v\">208</span> giờ. Giờ làm việc trong tháng vượt giờ tiêu chuẩn tháng của bộ phận được trả lương làm thêm giờ ít nhất bằng 150%; làm vào ngày lễ, tết ít nhất 300%; làm việc ban đêm (từ 22 giờ đến 6 giờ) được trả thêm ít nhất 30% (Điều 98 Bộ luật Lao động). Lương chuyển khoản vào tài khoản của Bên B tại <span class=\"tf-v\">MB Bank</span>; trả hằng tháng, chậm nhất vào ngày <span class=\"tf-v\">10</span> của tháng kế tiếp.</p><p class=\"tp-p\" style=\"text-align:justify\">5. Chế độ nâng lương, thưởng: theo quy chế lương, thưởng của Bên A.</p><p class=\"tp-h2\" style=\"text-align:justify\">Điều 4. Bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp</p><p class=\"tp-p\" style=\"text-align:justify\">Bên A và Bên B tham gia bảo hiểm xã hội bắt buộc, bảo hiểm y tế, bảo hiểm thất nghiệp theo quy định của pháp luật hiện hành; mức đóng theo quy định tại thời điểm đóng.</p><p class=\"tp-h2\" style=\"text-align:justify\">Điều 5. Quyền và nghĩa vụ của Bên B</p><p class=\"tp-p\" style=\"text-align:justify\">1. Được trả lương đầy đủ, đúng hạn; được hưởng các chế độ theo quy định của pháp luật và quy chế của Bên A.</p><p class=\"tp-p\" style=\"text-align:justify\">2. Hoàn thành công việc được giao; chấp hành nội quy lao động, quy định an toàn, vệ sinh lao động; giữ bí mật thông tin, tài liệu của Bên A theo cam kết bảo mật.</p><p class=\"tp-p\" style=\"text-align:justify\">3. Bồi thường thiệt hại do vi phạm theo quy định của pháp luật và nội quy lao động.</p><p class=\"tp-h2\" style=\"text-align:justify\">Điều 6. Quyền và nghĩa vụ của Bên A</p><p class=\"tp-p\" style=\"text-align:justify\">1. Bảo đảm việc làm, điều kiện làm việc và thực hiện đầy đủ các cam kết trong hợp đồng này.</p><p class=\"tp-p\" style=\"text-align:justify\">2. Trả lương đầy đủ, đúng hạn; đóng bảo hiểm cho Bên B theo quy định.</p><p class=\"tp-p\" style=\"text-align:justify\">3. Điều hành, quản lý Bên B theo nội quy lao động và quy định của pháp luật.</p><p class=\"tp-h2\" style=\"text-align:justify\">Điều 7. Điều khoản thi hành</p><p class=\"tp-p\" style=\"text-align:justify\">1. Những vấn đề chưa ghi trong hợp đồng này thực hiện theo nội quy lao động, thỏa ước lao động tập thể (nếu có) và quy định của pháp luật lao động.</p><p class=\"tp-p\" style=\"text-align:justify\">2. Hợp đồng có hiệu lực từ <span class=\"tf-v\">ngày …… tháng …… năm ……</span>, lập thành 02 bản có giá trị như nhau, mỗi bên giữ 01 bản.</p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><div class=\"tp-sign\"><div><b>NGƯỜI LAO ĐỘNG</b><i>(Ký, ghi rõ họ tên)</i>Phan Gia Bảo</div><div><b>NGƯỜI SỬ DỤNG LAO ĐỘNG</b><i>(Ký, đóng dấu, ghi rõ họ tên)</i>Lý Thanh Tùng</div></div>"},"BM07":{"ten":"Phiếu góp ý hành trình hội nhập","loai":"soan","ghi":"Góp ý thật lòng để hành trình của người mới sau tốt hơn.","nguoi":"nv","html":"<p class=\"tp-h1\" style=\"text-align:center\">PHIẾU GÓP Ý HÀNH TRÌNH HỘI NHẬP</p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-p\" style=\"text-align:justify\">Họ và tên: <span class=\"tf-v\">Phan Gia Bảo</span>    Bộ phận: <span class=\"tf-v\">Xưởng Sản xuất</span>    Ngày vào làm: <span class=\"tf-v\">14/09/2026</span></p><p class=\"tp-p\" style=\"text-align:justify\"><br></p><p class=\"tp-h2\" style=\"text-align:justify\">1. Ngày đầu bạn có được chuẩn bị đủ chỗ ngồi, thiết bị, tài khoản không?</p><p class=\"tp-p\" style=\"text-align:justify\">☐ Đã đủ    ☐ Còn thiếu: ……………………………………………………………………………………</p><p class=\"tp-h2\" style=\"text-align:justify\">2. Người đồng hành có hỗ trợ bạn kịp thời không?</p><p class=\"tp-p\" style=\"text-align:justify\">☐ Rất kịp thời    ☐ Bình thường    ☐ Chưa kịp thời – vì: ……………………………………………………………………………………</p><p class=\"tp-h2\" style=\"text-align:justify\">3. Thông tin về nội quy, chế độ, cách làm việc có rõ ràng không?</p><p class=\"tp-p\" style=\"text-align:justify\">☐ Rõ ràng    ☐ Còn chưa rõ: ……………………………………………………………………………………</p><p class=\"tp-h2\" style=\"text-align:justify\">4. Công ty nên làm khác đi điều gì để người mới sau thuận lợi hơn?</p><p class=\"tp-p\" style=\"text-align:justify\">……………………………………………………………………………………</p><p class=\"tp-p\" style=\"text-align:justify\">……………………………………………………………………………………</p>"}},"id":"HN01","ten":"Phan Gia Bảo","cty":"Công ty TNHH Đốm Sáng Health","cd":"Công nhân sản xuất","pb":"Xưởng Sản xuất","start":"2026-09-14","pe":"2026-11-12","jname":"Hành trình hội nhập - CHUNG","xong":0,"who":{"hcns":"Trịnh Thị Kim Ngân","tbp":"Lê Văn Phát","kc":"Võ Thành Đạt","kt":"Trịnh Thị Kim Ngân","bgd":"Lý Thanh Tùng","it":"Trịnh Thị Kim Ngân"},"ph":[["pre","Trước ngày đi làm","Chuẩn bị để ngày đầu không ai bị động"],["d1","Ngày đầu tiên","Đón, ký hồ sơ, phổ biến nội quy, bàn giao về bộ phận"],["w1","Tuần đầu tiên","Đồng hành, giới thiệu, trao đổi cuối tuần"],["pr","Trong thời gian thử việc","Theo dõi tiến độ, góp ý định kỳ"],["end","Kết thúc thử việc","Đánh giá và thông báo kết quả"],["off","Chính thức – chào đón","Ký hợp đồng, BHXH, chào đón thành viên mới"]],"roles":{"hcns":"Hành chính nhân sự","tbp":"Trưởng bộ phận","kc":"Người đồng hành","kt":"Kế toán","bgd":"Ban giám đốc","it":"Phụ trách thiết bị, tài khoản","nv":"Người mới"},"steps":[{"id":"b01","ph":"pre","due":"2026-09-09","t1":"","t2":"","title":"Xác nhận ngày đi làm, báo các bên liên quan","desc":"Xác nhận lại với người mới ngày giờ đi làm, địa điểm, người đón. Báo trưởng bộ phận và kế toán để chuẩn bị chỗ ngồi và tính lương từ ngày vào làm.","doc":"Thư mời nhận việc đã ký · Tên, số điện thoại người đón","own":"hcns","own2":["tbp","kt"],"x":"done","dAt":"2026-09-09","req":1,"law":"","bm":[],"moi":"co"},{"id":"b02","ph":"pre","due":"2026-09-11","t1":"","t2":"","title":"Gửi thư chào mừng và danh sách giấy tờ cần mang","desc":"Gửi qua email hoặc Zalo: giờ có mặt, địa chỉ, trang phục, người liên hệ. Ghi rõ giấy tờ mang theo để đối chiếu và nộp bản sao: CCCD, văn bằng, sổ BHXH, giấy khám sức khỏe.","doc":"Mẫu thư chào mừng · Danh sách giấy tờ cần mang · Bản đồ đường đến công ty","own":"hcns","own2":[],"x":"done","dAt":"2026-09-11","req":1,"law":"BLLĐ 2019 Điều 17 khoản 1 – không giữ bản chính giấy tờ tùy thân, văn bằng, chứng chỉ","bm":[],"moi":"co"},{"id":"b03","ph":"pre","due":"2026-09-12","t1":"","t2":"","title":"Soạn sẵn bộ hồ sơ ký ngày đầu","desc":"Hợp đồng thử việc, thỏa thuận bảo mật thông tin, biên bản bàn giao tài sản. Kiểm tra lương thử việc, số ngày thử việc khớp với thư mời nhận việc.","doc":"Hợp đồng thử việc (2 bản) · Thỏa thuận bảo mật thông tin · Biên bản bàn giao tài sản","own":"hcns","own2":[],"x":"done","dAt":"2026-09-12","req":1,"law":"BLLĐ 2019 Điều 24, 25 (thời gian thử việc), 26 (lương thử việc ít nhất 85%)","bm":[],"moi":""},{"id":"b04","ph":"pre","due":"2026-09-12","t1":"","t2":"","title":"Chuẩn bị chỗ ngồi, thiết bị, tài khoản","desc":"Sắp xếp chỗ ngồi, cài đặt máy tính; tạo email công ty, tài khoản phần mềm, thêm vào nhóm chat nội bộ; làm thẻ ra vào, đặt đồng phục đúng cỡ.","doc":"Bàn ghế · Máy tính · Email công ty · Tài khoản phần mềm · Nhóm chat nội bộ · Thẻ ra vào · Đồng phục","own":"it","own2":["hcns"],"x":"done","dAt":"2026-09-12","req":1,"law":"","bm":[],"moi":""},{"id":"b05","ph":"pre","due":"2026-09-13","t1":"","t2":"","title":"Phân công người đồng hành và lịch tuần đầu","desc":"Chọn một người cùng bộ phận đồng hành cùng người mới trong tháng đầu (có thể khác trưởng bộ phận). Lên lịch tuần đầu: ai hướng dẫn việc gì, ngày nào; gửi lịch cho phòng nhân sự.","doc":"Lịch tuần đầu · Danh sách đầu mối phối hợp","own":"tbp","own2":["kc"],"x":"done","dAt":"2026-09-13","req":1,"law":"","bm":[],"moi":""},{"id":"b06","ph":"pre","due":"2026-09-13","t1":"","t2":"","title":"Chuẩn bị quà chào đón","desc":"Chuẩn bị bộ quà tặng kèm thiệp chào mừng có chữ ký trưởng bộ phận – nhỏ nhưng tạo ấn tượng tốt ngày đầu.","doc":"Bộ quà tặng: sổ, bút, bình nước · Thiệp chào mừng có chữ ký trưởng bộ phận","own":"hcns","own2":[],"x":"done","dAt":"2026-09-13","req":0,"law":"","bm":[],"moi":""},{"id":"b07","ph":"d1","due":"2026-09-14","t1":"08:00","t2":"08:15","title":"Đón người mới, giới thiệu người phụ trách hội nhập","desc":"Đón ở lối vào, mời nước, giới thiệu bản thân và lịch ngày đầu; tặng quà chào đón.","doc":"Bộ quà tặng · Lịch ngày đầu in sẵn · Nước uống","own":"hcns","own2":[],"x":"done","dAt":"2026-09-14","req":1,"law":"","bm":[],"moi":"co"},{"id":"b08","ph":"d1","due":"2026-09-14","t1":"08:15","t2":"08:45","title":"Ký hồ sơ nhận việc, nhận bản sao giấy tờ","desc":"Người mới đọc kỹ rồi ký hợp đồng thử việc và các văn bản đã soạn. Giám đốc (hoặc người được ủy quyền) ký, giao lại người mới 01 bản. Chỉ nhận bản sao giấy tờ, đối chiếu bản chính rồi trả lại ngay.","doc":"Bộ hồ sơ ký ngày đầu (2 bản) · Con dấu · Túi hồ sơ lưu bản sao giấy tờ","own":"hcns","own2":["bgd","nv"],"x":"done","dAt":"2026-09-14","req":1,"law":"BLLĐ 2019 Điều 17 khoản 1, Điều 24","bm":["BM01","BM02"],"moi":"co"},{"id":"b09","ph":"d1","due":"2026-09-14","t1":"08:45","t2":"09:00","title":"Cấp tài khoản app, hướng dẫn người mới tự cập nhật hồ sơ","desc":"Cấp tài khoản app nhân viên, cùng người mới đăng nhập và chấm công thử một lần. Hướng dẫn người mới tự cập nhật hồ sơ trên app: CCCD, ngày sinh, địa chỉ, tài khoản ngân hàng, người phụ thuộc. Phòng nhân sự kiểm tra lại thông tin người mới gửi.","doc":"Tài khoản app nhân viên (mã đăng nhập, PIN) · Hướng dẫn chấm công Wi‑Fi","own":"hcns","own2":["nv"],"x":"done","dAt":"2026-09-14","req":1,"law":"","bm":[],"moi":"co"},{"id":"b10","ph":"d1","due":"2026-09-14","t1":"09:00","t2":"10:00","title":"Tìm hiểu công ty, nội quy và chế độ trên app","desc":"Người mới tự đọc, xem khóa đào tạo nội bộ “Hội nhập” trên app nhân viên: lịch sử, sứ mệnh, giá trị, sơ đồ tổ chức, sản phẩm – dịch vụ; nội quy lao động, giờ làm, chấm công, nghỉ phép, kỳ trả lương, thưởng và phúc lợi. Học xong bấm xác nhận đã đọc nội quy; phòng nhân sự giải đáp thắc mắc.","doc":"Khóa đào tạo nội bộ “Hội nhập” trên app · Nội quy lao động · Sổ tay nhân viên","own":"nv","own2":["hcns"],"x":"done","dAt":"2026-09-14","req":1,"law":"BLLĐ 2019 Điều 118 khoản 4 – nội quy lao động phải được thông báo đến người lao động","bm":[],"moi":"own"},{"id":"b11","ph":"d1","due":"2026-09-14","t1":"10:00","t2":"10:30","title":"Giới thiệu với các phòng ban, bàn giao về bộ phận","desc":"Dẫn người mới chào ban giám đốc, trưởng các bộ phận và đồng nghiệp; bàn giao cho trưởng bộ phận và người đồng hành.","doc":"Sơ đồ tổ chức · Danh sách người cần chào","own":"hcns","own2":["tbp","kc"],"x":"done","dAt":"2026-09-14","req":1,"law":"","bm":[],"moi":"co"},{"id":"b12","ph":"d1","due":"2026-09-14","t1":"13:30","t2":"14:30","title":"Giao mô tả công việc và mục tiêu tuần đầu","desc":"Trưởng bộ phận trao đổi mô tả công việc, kết quả mong đợi trong thời gian thử việc, mục tiêu tuần đầu và cách đánh giá.","doc":"Mô tả công việc · Mục tiêu thử việc · Tiêu chí đánh giá","own":"tbp","own2":["kc"],"x":"done","dAt":"2026-09-14","req":1,"law":"","bm":[],"moi":"co"},{"id":"b13","ph":"d1","due":"2026-09-14","t1":"14:30","t2":"15:00","title":"Bàn giao tài sản, công cụ làm việc","desc":"Bàn giao máy tính, thiết bị, thẻ ra vào, đồng phục, chìa khóa tủ; hai bên ký biên bản.","doc":"Biên bản bàn giao (2 bản) · Máy tính · Thẻ ra vào · Đồng phục · Chìa khóa tủ","own":"hcns","own2":["it"],"x":"done","dAt":"2026-09-14","req":0,"law":"","bm":["BM03"],"moi":"co"},{"id":"b14","ph":"d1","due":"2026-09-14","t1":"16:30","t2":"17:00","title":"Hỏi thăm cuối ngày đầu","desc":"Trò chuyện 10–15 phút: ngày đầu thế nào, còn vướng gì, cần hỗ trợ gì; ghi lại để xử lý ngay.","doc":"Phiếu ghi nhận ý kiến ngày đầu","own":"hcns","own2":[],"x":"done","dAt":"2026-09-14","req":0,"law":"","bm":[],"moi":"co"},{"id":"b15","ph":"w1","due":"2026-09-15","t1":"","t2":"","title":"Đồng hành trong công việc hằng ngày","desc":"Người đồng hành hướng dẫn quy trình, công cụ, đầu mối phối hợp; giao việc nhỏ để người mới làm thử và góp ý ngay trong ngày.","doc":"Danh sách việc giao thử · Tài liệu quy trình của bộ phận","own":"kc","own2":["tbp"],"x":"done","dAt":"2026-09-15","req":1,"law":"","bm":[],"moi":"co"},{"id":"b16","ph":"w1","due":"2026-09-16","t1":"","t2":"","title":"Giới thiệu người mới với toàn công ty","desc":"Đăng lời chào mừng trên nhóm chat hoặc bản tin nội bộ: tên, vị trí, bộ phận. Hỏi ý người mới trước khi đăng ảnh, thông tin cá nhân.","doc":"Ảnh và lời giới thiệu đã được người mới đồng ý","own":"hcns","own2":[],"x":"done","dAt":"2026-09-16","req":0,"law":"","bm":[],"moi":""},{"id":"b17","ph":"w1","due":"2026-09-20","t1":"","t2":"","title":"Trò chuyện đánh giá tuần đầu","desc":"Người mới tự nhìn lại tuần đầu (thuận lợi, khó khăn, cần hỗ trợ); trưởng bộ phận nhận xét. Đây là trao đổi nội bộ để hỗ trợ kịp thời – không thay cho thông báo kết quả thử việc.","doc":"Phiếu trao đổi tuần đầu","own":"hcns","own2":["tbp","nv"],"x":"done","dAt":"2026-09-20","req":1,"law":"","bm":["BM04"],"moi":"co"},{"id":"b18","ph":"pr","due":"2026-10-13","t1":"","t2":"","title":"Gặp định kỳ giữa thời gian thử việc","desc":"Xem tiến độ so với mục tiêu thử việc, góp ý cụ thể, điều chỉnh hỗ trợ.","doc":"Bảng theo dõi mục tiêu thử việc","own":"tbp","own2":["hcns"],"x":"done","dAt":"2026-10-13","req":0,"law":"","bm":[],"moi":"co"},{"id":"b23","ph":"end","due":"2026-11-02","t1":"","t2":"","title":"Người mới tự đánh giá kết quả thử việc","desc":"Tự nhìn lại các mục tiêu đã giao: việc đã làm tốt, việc cần cải thiện, hỗ trợ cần thêm. Gửi trưởng bộ phận trước buổi đánh giá kết quả thử việc.","doc":"Phiếu tự đánh giá thử việc","own":"nv","own2":["tbp"],"x":"done","dAt":"2026-11-02","req":1,"law":"","bm":["BM05"],"moi":"own"},{"id":"b19","ph":"end","due":"2026-11-05","t1":"","t2":"","title":"Trưởng bộ phận đánh giá kết quả thử việc","desc":"Đánh giá theo mục tiêu đã giao ngày đầu; đề xuất Đạt / Không đạt gửi phòng nhân sự và ban giám đốc.","doc":"Phiếu đánh giá kết quả thử việc","own":"tbp","own2":["hcns"],"x":"done","dAt":"2026-11-06","req":1,"law":"","bm":[],"moi":""},{"id":"b20","ph":"end","due":"2026-11-12","t1":"","t2":"","title":"Thông báo kết quả thử việc cho người lao động","desc":"Thông báo khi kết thúc thời gian thử việc. Đạt: ký hợp đồng lao động. Không đạt: chấm dứt hợp đồng thử việc.","doc":"Thông báo kết quả thử việc","own":"hcns","own2":["bgd"],"x":"todo","dAt":"","req":1,"law":"BLLĐ 2019 Điều 27","bm":[],"moi":"co"},{"id":"b21","ph":"off","due":"2026-11-13","t1":"","t2":"","title":"Ký hợp đồng lao động, đăng ký BHXH","desc":"Ký hợp đồng lao động, cập nhật lương chính thức. Kế toán đăng ký tham gia BHXH, BHYT, BHTN cho người lao động.","doc":"Hợp đồng lao động (2 bản) · Quyết định lương chính thức · Hồ sơ đăng ký BHXH","own":"hcns","own2":["kt"],"x":"todo","dAt":"","req":1,"law":"Luật BHXH 2024 – thời hạn đăng ký tham gia (chưa trích điều)","bm":["BM06"],"moi":"co"},{"id":"b22","ph":"off","due":"2026-11-15","t1":"","t2":"","title":"Chào đón thành viên chính thức","desc":"Chúc mừng trong buổi họp hoặc nhóm chung; trao thẻ nhân viên, đồng phục. Hỏi người mới góp ý về quá trình hội nhập để cải thiện hành trình.","doc":"Thẻ nhân viên · Đồng phục · Quà chúc mừng · Phiếu góp ý hội nhập","own":"hcns","own2":["nv"],"x":"todo","dAt":"","req":0,"law":"","bm":["BM07"],"moi":"co"}]}};
